import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, isAbsolute, relative, resolve } from 'node:path'

// Local stand-in for the S3-compatible store. Keys are generated by the server.
// Set UPLOAD_DIR to move the directory; the default stays under .data, which is gitignored.

const LOGO_KEY = /^logos\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export function uploadsRoot(): string {
  const configured = process.env.UPLOAD_DIR?.trim()
  if (configured) return resolve(configured)
  return resolve(process.cwd(), '.data', 'uploads')
}

export function storedFilePath(key: string, root = uploadsRoot()): string {
  if (!LOGO_KEY.test(key)) throw new Error('Invalid storage key')
  const rootPath = resolve(root)
  const full = resolve(rootPath, key)
  const rel = relative(rootPath, full)
  if (rel.startsWith('..') || isAbsolute(rel)) throw new Error('Invalid storage key')
  return full
}

export async function writeStoredFile(key: string, bytes: Uint8Array, root = uploadsRoot()): Promise<void> {
  const path = storedFilePath(key, root)
  await mkdir(dirname(path), { recursive: true })
  await writeFile(path, bytes)
}

export async function readStoredFile(key: string, root = uploadsRoot()): Promise<Buffer | null> {
  try {
    return await readFile(storedFilePath(key, root))
  }
  catch (error) {
    if (isNotFound(error)) return null
    throw error
  }
}

export async function deleteStoredFile(key: string, root = uploadsRoot()): Promise<void> {
  await rm(storedFilePath(key, root), { force: true })
}

function isNotFound(error: unknown): boolean {
  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT'
}
